import type { GeneratedPolicy } from '@hfos/core';
import type { Metadata } from 'next';
import { notFound } from 'next/navigation';
import { publicEnv } from '@/lib/env';

/**
 * The privacy policy and terms HandsFreeOS hosts for a business: `/legal/<business>/privacy`.
 *
 * Signed out, and plain on purpose — a carrier's reviewer opens this looking for one paragraph, and the
 * quickest page to read is the one most likely to be read. The words are generated by core from what the
 * business told the registration; the worker serves them.
 */
async function fetchPolicy(site: string, kind: string): Promise<GeneratedPolicy | null> {
  try {
    const res = await fetch(`${publicEnv.workerUrl}/public/legal/${site}/${kind}`, {
      next: { revalidate: 300 },
    });
    if (!res.ok) return null;
    const body = (await res.json()) as { policy?: GeneratedPolicy };
    return body.policy ?? null;
  } catch {
    return null;
  }
}

export async function generateMetadata({
  params,
}: {
  params: Promise<{ site: string; kind: string }>;
}): Promise<Metadata> {
  const { site, kind } = await params;
  const policy = await fetchPolicy(site, kind);
  return { title: policy?.title ?? 'Policy', robots: { index: false } };
}

export default async function LegalPage({
  params,
}: {
  params: Promise<{ site: string; kind: string }>;
}) {
  const { site, kind } = await params;
  if (kind !== 'privacy' && kind !== 'terms') notFound();
  const policy = await fetchPolicy(site, kind);
  if (!policy) notFound();
  return (
    <main className="mx-auto min-h-dvh max-w-[680px] bg-bg px-5 py-10 text-text">
      <h1 className="text-[24px] font-semibold">{policy.title}</h1>
      <p className="mt-3 text-[14.5px] leading-relaxed text-text-2">{policy.intro}</p>
      {policy.sections.map((section) => (
        <section key={section.heading} className="mt-7">
          <h2 className="text-[16px] font-semibold">{section.heading}</h2>
          {section.paragraphs.map((paragraph, i) => (
            <p
              key={i}
              className="mt-2 whitespace-pre-line text-[14.5px] leading-relaxed text-text-2"
            >
              {paragraph}
            </p>
          ))}
        </section>
      ))}
      <p className="mt-8 text-[13px] text-text-3">Last updated: {policy.updated}</p>
    </main>
  );
}
